export function validarFormulario(e){const o=e.querySelector("#nombre").value.trim(),t=e.querySelector("#correo").value.trim(),n=e.querySelector("#comentario").value.trim();return o&&t&&n?t.includes("@")?{valido:!0,datos:{nombre:o,email:t,mensaje:n}}:{valido:!1,error:"Ingresa un correo válido."}:{valido:!1,error:"Por favor completa todos los campos."}}export function mostrarEstado(e,o){const t="ok"===o?"✅ Comentario enviado":"⚠️ Atención",n={body:e};"Notification"in window?"granted"!==Notification.permission?"denied"===Notification.permission?alert(`${t}\n${e}`):Notification.requestPermission().then(o=>{"granted"===o?new Notification(t,n):alert(`${t}\n${e}`)}):new Notification(t,n):alert(`${t}\n${e}`)}export function mostrarComentarios(e){const o=document.getElementById("lista-comentarios");if(o){if(o.innerHTML="",!e||0===e.length){const e=document.createElement("p");return e.className="comentarios-vacio",e.textContent="Aún no hay comentarios. ¡Sé el primero!",void o.appendChild(e)}[...e].reverse().forEach(e=>{const t=document.createElement("article");t.className="comentario";const n=document.createElement("div");n.className="comentario-cabecera";const a=document.createElement("span");a.className="comentario-nombre",a.textContent=e.nombre;const r=document.createElement("time");r.className="comentario-fecha",r.textContent=e.fecha||"",n.append(a,r);const i=document.createElement("p");i.className="comentario-mensaje",i.textContent=e.mensaje,t.append(n,i),o.appendChild(t)})}}